mapper.select:
SELECT cu.id, cu.company_name, AS audit_time, COALESCE(SUM(p.planned_recruit), 0) AS position_count, (
AND sis.student_id IN #{sid}
AND 1 = 0 ) AS admitted_count, CASE cu.status WHEN 1 THEN '正常' WHEN 0 THEN '已禁用' ELSE '未知' END AS status, cu.company_tag FROM company_users cu LEFT JOIN position p ON cu.id = p.company_id AND p.status IN ('active', 'paused') WHERE cu.audit_status = 1 GROUP BY cu.id, cu.company_name, cu.audit_time, cu.create_time, cu.status, cu.company_tag ORDER BY DESC, cu.id DESC LIMIT #{offset}, #{pageSize}

SELECT m.id, d.name AS college, m.name AS major_name, COUNT(DISTINCT su.id) AS total_count, COUNT(DISTINCT CASE WHEN sis.status IN (2, 3, 4) THEN su.id END) AS internship_count, ROUND(COUNT(DISTINCT CASE WHEN sis.status IN (2, 3, 4) THEN su.id END) * 100.0 / COUNT(DISTINCT su.id), 1) AS internship_rate FROM major m LEFT JOIN department d ON m.department_id = d.id JOIN student_users su ON m.id = su.major_id
AND su.id IN #{sid}
AND 1 = 0
LEFT JOIN student_internship_status sis ON su.id = sis.student_id GROUP BY m.id, d.name, m.name ORDER BY m.id LIMIT #{offset}, #{pageSize}

SELECT COUNT(DISTINCT su.major_id) FROM student_users su
su.id IN #{sid}
1 = 0

SELECT COUNT(*) FROM student_users su
su.id IN #{sid}
1 = 0

SELECT COUNT(*) FROM student_users su WHERE su.status = 1 AND IN (0,1) AND NOT AND NOT
AND su.id IN #{sid}
AND 1 = 0

SELECT COUNT(DISTINCT sis.student_id) FROM student_internship_status sis WHERE sis.status IN (2, 3, 4)
AND sis.student_id IN #{sid}
AND 1 = 0

SELECT COUNT(*) FROM student_application sa WHERE 1 = 1
AND sa.student_id IN #{sid}
AND 1 = 0

SELECT COALESCE(SUM(download_count), 0)
FROM learning_resources
WHERE created_time BETWEEN #{startDate} AND #{endDate}
